// The MC's sprite, cut into recolourable layers (Fase 10).
//
// Generated by scripts/build-character-layers.mjs — do not hand-edit the numbers.
// Re-run the script and paste its output if the segmentation changes.
//
// The whole point: every layer here is made of the ORIGINAL sprite's pixels, so
// the art style is not imitated, it is reused. Three earlier attempts drew the MC
// procedurally (rect lists, hand-authored string art, generated profiles) and all
// three read as cheap next to the source, because geometry does not reproduce a
// drawing.
//
// A layer carries two things beyond its image:
//
//   `stops`  — the luminance values, at percentiles of the layer's own pixels,
//              where each ramp entry sits. Percentiles and not equal bins: with
//              equal bins the cap's darkest anchor came out dark RED (its shadow
//              outnumbers its outline) and every recolour grew a red halo.
//   `source` — the sprite's own colour at each stop, so recolouring with this
//              exact ramp is a no-op and the identity render is the original.
//
// src/ui/characterDraw.ts remaps luminance onto a target ramp between the stops,
// which moves the hue and keeps the artist's shading.

// Layers are addressed by id everywhere: the asset key is `mc-layer-<id>` and the
// file is /assets/characters/layers/<id>.png.
export type LayerId =
  | "skin"
  | "hair"
  | "top"
  | "print"
  | "bottom"
  | "shoes"
  | "cap"
  | "brim"
  | "lens"
  | "frame"
  | "eyesOpen";

// Which palette ramp recolours a layer. Some roles are shared (lens and frame are
// both "glass") and three are fixed art that must not follow the outfit: the visor
// stays black, glass stays glass and an eye keeps its own colour.
export type LayerRole =
  | "skin"
  | "hair"
  | "top"
  | "print"
  | "bottom"
  | "shoes"
  | "cap"
  | "brim"
  | "glass"
  | "eye";

export interface CharacterLayer {
  id: LayerId;
  role: LayerRole;
  stops: readonly number[];
  source: readonly string[];
}

// The source sprite's own dimensions. Everything composites at this size and is
// scaled once, so no layer can drift out of register with another.
export const LAYER_SIZE = { w: 101, h: 240 } as const;

