// Bottom to top. The head stack is the part that matters: hair goes UNDER the cap
// (they are exclusive, but the order has to be right either way) and the eyes go
// last so nothing can bury them — the eyes are what make him a person.
export const layerOrder: readonly LayerId[] = [
  "skin",
  "bottom",
  "top",
  "print",
  "shoes",
  "hair",
  "cap",
  "brim",
  "lens",
  "frame",
  "eyesOpen",
];

export function layerById(id: LayerId): CharacterLayer {
  const found = characterLayers.find((layer) => layer.id === id);
  if (!found) throw new Error(`capa desconocida: ${id}`);
  return found;
}
